mapper.select:
SELECT

FROM skill_flow
WHERE deleted_at IS NULL
AND created_by = #{ownerUserId}
AND enabled = #{enabled}

    AND (LOWER(name) LIKE CONCAT('%', LOWER(#{keyword}), '%')
    OR LOWER(code) LIKE CONCAT('%', LOWER(#{keyword}), '%'))

AND created_by = #{createdBy}
ORDER BY updated_at DESC, id DESC

mapper.delete:
DELETE
FROM skill_metric_readiness
WHERE metric_id = #{metricId}
  AND data_date = #{dataDate}

mapper.select:
SELECT

FROM skill_metric_readiness
WHERE metric_id = #{metricId}
  AND data_date = #{dataDate}

SELECT

FROM skill_metric_readiness
WHERE data_date = #{dataDate}
  AND status = 'READY'
  AND metric_id IN
#{metricId}

SELECT *
FROM skill_flow_execution
WHERE id = #{id}

SELECT *
FROM skill_flow_execution
WHERE trigger_user_id = #{userId}
  AND conversation_id = #{conversationId}
ORDER BY CASE WHEN active_guard_key IS NOT NULL THEN 0 ELSE 1 END, created_at DESC
LIMIT 1

SELECT * FROM skill_flow_execution WHERE 1=1
AND trigger_user_id=#{userId}
AND status=#{status}
AND trigger_user_id=#{createdBy}
ORDER BY created_at DESC LIMIT 500

SELECT *
FROM skill_flow_node_execution
WHERE id = #{id}

SELECT COUNT(*)
FROM skill_flow_node_execution
WHERE flow_execution_id = #{flowExecutionId}
  AND status = 'RUNNING'
  AND lease_expires_at >= #{now}

SELECT COALESCE(MAX(attempt_no), 0)
FROM skill_flow_node_attempt
WHERE node_execution_id = #{nodeId}
